CREATE TABLE topology_links(id UUID PRIMARY KEY,source_device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,target_device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,bandwidth_mbps DOUBLE PRECISION,latency_ms DOUBLE PRECISION,packet_loss_percent DOUBLE PRECISION,utilization_percent DOUBLE PRECISION,status VARCHAR(30) NOT NULL DEFAULT 'UP',discovery_method VARCHAR(40) NOT NULL DEFAULT 'MANUAL');CREATE INDEX idx_topology_source ON topology_links(source_device_id);CREATE INDEX idx_topology_target ON topology_links(target_device_id);